{
  "name": "Eorzea Card Maker",
  "description": "A high-quality FFXIV character card generator for players to create and share their character profiles with customizable frames, image manipulation, and personality traits.",
  "requestFramePermissions": [
    "camera"
  ]
}

export type Orientation = 'portrait' | 'landscape';

export interface CharacterInfo {
  name: string;
  server: string;
  gender: string;
  race: string;
  age: string;
  height: string;
  orientation: string;
  job: string;
  personality: string;
  background: string;
  birthplace: string;
  likes: string;
  dislikes: string;
}

export interface Traits {
  muscles: number; // 0: 較少, 100: 較多
  temperature: number; // 0: 較低, 100: 較高
  voiceVolume: number; // 0: 小聲, 100: 大聲
  voicePitch: number; // 0: 低沉, 100: 高亢
  sensitivity: number; // 0: 冷淡, 100: 豐沛
  appetite: number; // 0: 小鳥胃, 100: 大胃王
  tableManners: number; // 0: 很髒, 100: 很乾淨
  alcoholPref: number; // 0: 討厭, 100: 喜歡
  alcoholTolerance: number; // 0: 壞, 100: 好
  athleticism: number; // 0: 不太好, 100: 很好
  combatPref: number; // 0: 討厭, 100: 喜歡
  combatSkill: number; // 0: 不擅長, 100: 擅長
  combatRange: number; // 0: 遠程, 100: 近戰
}

export interface ImageTransform {
  x: number;
  y: number;
  scale: number;
  rotate: number;
}

export interface FrameStyle {
  id: string;
  name: string;
  borderColor: string;
  bgGradient: string;
  accentColor: string;
  textColor: string;
}

