            <div className="space-y-2">
              <SliderInput label="體型" value={traits.muscles} onChange={(v) => updateTrait('muscles', v)} leftLabel="較少" rightLabel="較多" />
              <SliderInput label="體溫" value={traits.temperature} onChange={(v) => updateTrait('temperature', v)} leftLabel="較低" rightLabel="較高" />
              <SliderInput label="聲量" value={traits.voiceVolume} onChange={(v) => updateTrait('voiceVolume', v)} leftLabel="小聲" rightLabel="大聲" />
              <SliderInput label="音調" value={traits.voicePitch} onChange={(v) => updateTrait('voicePitch', v)} leftLabel="低沉" rightLabel="高亢" />
              <SliderInput label="感性程度" value={traits.sensitivity} onChange={(v) => updateTrait('sensitivity', v)} leftLabel="冷淡" rightLabel="豐沛" />
              <SliderInput label="飯量" value={traits.appetite} onChange={(v) => updateTrait('appetite', v)} leftLabel="小鳥胃" rightLabel="大胃王" />
              <SliderInput label="酒量" value={traits.alcoholTolerance} onChange={(v) => updateTrait('alcoholTolerance', v)} leftLabel="不太好" rightLabel="很好" />
              <SliderInput label="運動神經" value={traits.athleticism} onChange={(v) => updateTrait('athleticism', v)} leftLabel="不太好" rightLabel="很好" />
              <SliderInput label="戰鬥範圍" value={traits.combatRange} onChange={(v) => updateTrait('combatRange', v)} leftLabel="遠程" rightLabel="近戰" />
            </div>
          </section>

        </div>

        {/* Right Column: Sticky Preview Area */}
        <div className="lg:col-span-7 xl:col-span-8 relative" ref={previewContainerRef}>
          <div className="sticky top-24 flex flex-col items-center w-full min-h-[600px] p-8 bg-slate-900/40 rounded-3xl border border-slate-800/50 backdrop-blur-md shadow-2xl">
            <div className="mb-8 text-center">
              <h3 className="text-slate-500 text-xs font-bold uppercase tracking-widest">即時預覽 Preview</h3>
              <p className="text-[10px] text-slate-600 mt-1">卡片寬度將根據螢幕自動縮放顯示</p>
            </div>

            {/* Scaling Wrapper to prevent overlap */}
            <div 
              style={{ 
                transform: `scale(${previewScale})`, 
                transformOrigin: 'top center',
                transition: 'transform 0.2s ease-out',
                width: orientation === 'landscape' ? '800px' : '450px',
                height: orientation === 'landscape' ? '450px' : '800px',
              }}
              className="relative shadow-2xl"
            >
              <Card 
                id="character-card-preview"
                info={info}
                traits={traits}
                orientation={orientation}
                style={style}
                image={image}
                transform={transform}
                ref={cardRef}
              />
            </div>

            <div className="mt-12 bg-blue-500/5 border border-blue-500/20 rounded-xl p-6 max-w-sm text-center">
               <p className="text-xs text-blue-300 italic mb-2">「光之戰士，這是你在艾歐澤亞的軌跡。」</p>
               <p className="text-[10px] text-slate-500">提示：設定完成後點擊右上角的「儲存卡片」按鈕即可匯出 2x 高畫質 PNG 檔案。</p>
            </div>
          </div>
        </div>
      </main>

      {/* Background Decor */}
      <div className="fixed inset-0 pointer-events-none -z-10 overflow-hidden opacity-30">
         <div className="absolute top-[-10%] left-[-5%] w-[50%] h-[50%] bg-blue-600/10 blur-[150px] rounded-full" />
         <div className="absolute bottom-[-10%] right-[-5%] w-[50%] h-[50%] bg-purple-600/10 blur-[150px] rounded-full" />
         <div className="absolute top-[30%] right-[10%] w-[30%] h-[30%] bg-emerald-600/5 blur-[120px] rounded-full" />
      </div>
    </div>
  );
};

export default App;

import React, { forwardRef } from 'react';
import { CharacterInfo, Traits, Orientation, FrameStyle, ImageTransform } from '../types';

interface CardProps {
  info: CharacterInfo;
  traits: Traits;
  orientation: Orientation;
  style: FrameStyle;
  image: string | null;
  transform: ImageTransform;
  id?: string;
}

const Card = forwardRef<HTMLDivElement, CardProps>(({ info, traits, orientation, style, image, transform, id }, ref) => {
  const isPortrait = orientation === 'portrait';

  const containerStyle: React.CSSProperties = {
    width: isPortrait ? '450px' : '800px',
    height: isPortrait ? '800px' : '450px',
    background: style.bgGradient,
    border: `8px double ${style.borderColor}`,
    position: 'relative',
    overflow: 'hidden',
    boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5)',
    transition: 'all 0.3s ease'
  };

  const imageContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: isPortrait ? '100%' : '50%',
    height: isPortrait ? '50%' : '100%',
    overflow: 'hidden',
    borderBottom: isPortrait ? `4px solid ${style.borderColor}` : 'none',
    borderRight: !isPortrait ? `4px solid ${style.borderColor}` : 'none',
    backgroundColor: '#000'
  };

  const contentContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: isPortrait ? '50%' : 0,
    left: isPortrait ? 0 : '50%',
    width: isPortrait ? '100%' : '50%',
    height: isPortrait ? '50%' : '100%',
    padding: '1.5rem',
    overflowY: 'auto',
    color: style.textColor,
    display: 'flex',
    flexDirection: 'column',
    gap: '0.75rem',
    scrollbarWidth: 'none', // For Firefox
  };

  const TraitBar = ({ label, value, left, right }: { label: string, value: number, left: string, right: string }) => {
    if (value === 50) return null; // Assume 50 is default/don't show
    return (
      <div className="text-[10px] flex flex-col gap-0.5">
        <div className="flex justify-between font-bold opacity-70">
          <span>{label}</span>
          <span>{value < 50 ? left : right}</span>
        </div>
        <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
          <div 
            className="h-full bg-current opacity-60" 
            style={{ 
              width: `${Math.abs(value - 50) * 2}%`,
              marginLeft: value > 50 ? '50%' : `${value}%`
            }} 
          />
        </div>
      </div>
    );
  };

  return (
    <div id={id} ref={ref} style={containerStyle} className="ff-font select-none">
      <style>{`
        .card-content-scroll::-webkit-scrollbar {
          display: none;
        }
      `}</style>

      {/* Character Image */}
      <div style={imageContainerStyle}>
        {image ? (
          <img
            src={image}
            alt="Character"
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) rotate(${transform.rotate}deg)`,
              transformOrigin: 'center center'
            }}
          />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 bg-slate-900/50">
             <span className="text-4xl mb-2">👤</span>
             <p className="text-sm">尚未上傳角色圖片</p>
          </div>
        )}

        {/* Overlay Overlay Info */}
        <div className="absolute bottom-0 left-0 w-full p-4 bg-gradient-to-t from-black/80 to-transparent">
          <h1 className="text-2xl font-bold tracking-tight drop-shadow-md">{info.name || '角色姓名'}</h1>
          <p className="text-xs opacity-80 tracking-widest">{info.server || 'SERVER NAME'}</p>
        </div>
      </div>

      {/* Profile Details */}
      <div style={contentContainerStyle} className="card-content-scroll">
        {/* Basic Stats Grid */}
        <div className="grid grid-cols-2 gap-2 text-xs border-b border-white/10 pb-3">
          {info.race && <div><span className="opacity-50 mr-2">種族</span>{info.race}</div>}
          {info.gender && <div><span className="opacity-50 mr-2">性別</span>{info.gender}</div>}
          {info.job && <div><span className="opacity-50 mr-2">職業</span>{info.job}</div>}
          {info.age && <div><span className="opacity-50 mr-2">歲數</span>{info.age}</div>}
          {info.height && <div><span className="opacity-50 mr-2">身高</span>{info.height}</div>}
          {info.orientation && <div><span className="opacity-50 mr-2">性向</span>{info.orientation}</div>}
          {info.birthplace && <div><span className="opacity-50 mr-2">出生地</span>{info.birthplace}</div>}
        </div>

        {/* Text Sections */}
        {info.personality && (
          <div className="space-y-1">
            <h3 className="text-[10px] font-bold uppercase tracking-widest opacity-40">性格</h3>
            <p className="text-xs leading-relaxed">{info.personality}</p>
          </div>
        )}

        {info.background && (
          <div className="space-y-1">
            <h3 className="text-[10px] font-bold uppercase tracking-widest opacity-40">背景故事</h3>
            <p className="text-xs leading-relaxed">{info.background}</p>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          {info.likes && (
             <div className="space-y-1">
                <h3 className="text-[10px] font-bold uppercase tracking-widest opacity-40 text-green-400">喜歡</h3>
                <p className="text-[11px] leading-snug">{info.likes}</p>
             </div>
          )}
          {info.dislikes && (
             <div className="space-y-1">
                <h3 className="text-[10px] font-bold uppercase tracking-widest opacity-40 text-red-400">討厭</h3>
                <p className="text-[11px] leading-snug">{info.dislikes}</p>
             </div>
          )}
        </div>

        {/* Trait Bars Section */}
        <div className="grid grid-cols-2 gap-x-4 gap-y-2 pt-2 border-t border-white/10">
          <TraitBar label="體型" value={traits.muscles} left="較少肌肉" right="較多肌肉" />
          <TraitBar label="體溫" value={traits.temperature} left="較低" right="較高" />
          <TraitBar label="聲量" value={traits.voiceVolume} left="小聲" right="大聲" />
          <TraitBar label="音調" value={traits.voicePitch} left="低沉" right="高亢" />
          <TraitBar label="感性" value={traits.sensitivity} left="冷淡" right="豐沛" />
          <TraitBar label="食量" value={traits.appetite} left="小鳥胃" right="大胃王" />
          <TraitBar label="酒量" value={traits.alcoholTolerance} left="不太好" right="很好" />
          <TraitBar label="運動" value={traits.athleticism} left="不太好" right="很好" />
          <TraitBar label="戰鬥" value={traits.combatRange} left="遠程" right="近戰" />
        </div>
      </div>

      {/* Decorative Frame Elements */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
      <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
    </div>
  );
});

export default Card;

import React, { useState, useRef, useEffect } from 'react';
import Card from './components/Card';
import SliderInput from './components/SliderInput';
import { CharacterInfo, Traits, Orientation, ImageTransform, FrameStyle } from './types';
import { FRAME_STYLES, JOBS, RACES } from './constants';
import { improveDescription } from './services/geminiService';

const initialInfo: CharacterInfo = {
  name: '',
  server: '',
  gender: '',
  race: '',
  age: '',
  height: '',
  orientation: '',
  job: '',
  personality: '',
  background: '',
  birthplace: '',
  likes: '',
  dislikes: '',
};

const initialTraits: Traits = {
  muscles: 50,
  temperature: 50,
  voiceVolume: 50,
  voicePitch: 50,
  sensitivity: 50,
  appetite: 50,
  tableManners: 50,
  alcoholPref: 50,
  alcoholTolerance: 50,
  athleticism: 50,
  combatPref: 50,
  combatSkill: 50,
  combatRange: 50,
};

const initialTransform: ImageTransform = {
  x: 0,
  y: 0,
  scale: 1,
  rotate: 0,
};

const App: React.FC = () => {
  const [info, setInfo] = useState<CharacterInfo>(initialInfo);
  const [traits, setTraits] = useState<Traits>(initialTraits);
  const [orientation, setOrientation] = useState<Orientation>('portrait');
  const [style, setStyle] = useState<FrameStyle>(FRAME_STYLES[0]);
  const [image, setImage] = useState<string | null>(null);
  const [transform, setTransform] = useState<ImageTransform>(initialTransform);
  const [isImproving, setIsImproving] = useState(false);
  const [previewScale, setPreviewScale] = useState(1);

  const cardRef = useRef<HTMLDivElement>(null);
  const previewContainerRef = useRef<HTMLDivElement>(null);

  // Auto-scale the preview to fit the container width
  useEffect(() => {
    const handleResize = () => {
      if (previewContainerRef.current) {
        const containerWidth = previewContainerRef.current.offsetWidth - 48; // padding
        const cardWidth = orientation === 'landscape' ? 800 : 450;
        if (containerWidth < cardWidth) {
          setPreviewScale(containerWidth / cardWidth);
        } else {
          setPreviewScale(1);
        }
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [orientation]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImage(event.target?.result as string);
        setTransform(initialTransform);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleExport = async () => {
    if (cardRef.current) {
      const canvas = await (window as any).html2canvas(cardRef.current, {
        useCORS: true,
        backgroundColor: null,
        scale: 2 // Higher resolution
      });
      const link = document.createElement('a');
      link.download = `FF14_CharacterCard_${info.name || 'Export'}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  const updateInfo = (field: keyof CharacterInfo, value: string) => {
    setInfo(prev => ({ ...prev, [field]: value }));
  };

  const updateTrait = (field: keyof Traits, value: number) => {
    setTraits(prev => ({ ...prev, [field]: value }));
  };

  const handleImproveText = async (type: 'personality' | 'background') => {
    setIsImproving(true);
    const improved = await improveDescription(info[type], type);
    updateInfo(type, improved);
    setIsImproving(false);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 p-4 sticky top-0 z-50 shadow-xl">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-xl shadow-lg shadow-blue-500/20">C</div>
            <h1 className="text-xl font-bold tracking-tight ff-font">Eorzea Card Maker</h1>
          </div>
          <button
            onClick={handleExport}
            className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-full font-bold transition shadow-lg shadow-blue-600/30 flex items-center space-x-2"
          >
            <span>💾 儲存卡片</span>
          </button>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto p-4 lg:p-10 grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20">

        {/* Left Column: Editor Controls */}
        <div className="lg:col-span-5 xl:col-span-4 space-y-8 pb-20">

          {/* Card Config */}
          <section className="bg-slate-900 rounded-2xl p-6 border border-slate-800 shadow-inner">
            <h2 className="text-lg font-bold mb-4 flex items-center text-blue-400">
              <span className="mr-2">🎴</span> 基本設定
            </h2>
            <div className="grid grid-cols-2 gap-4 mb-6">
              <button
                onClick={() => setOrientation('portrait')}
                className={`p-3 rounded-xl border-2 transition ${orientation === 'portrait' ? 'border-blue-500 bg-blue-500/10' : 'border-slate-800 bg-slate-800/50'}`}
              >
                直式 Portrait
              </button>
              <button
                onClick={() => setOrientation('landscape')}
                className={`p-3 rounded-xl border-2 transition ${orientation === 'landscape' ? 'border-blue-500 bg-blue-500/10' : 'border-slate-800 bg-slate-800/50'}`}
              >
                橫式 Landscape
              </button>
            </div>

            <div className="space-y-4">
              <label className="block text-sm font-medium text-slate-400">框架風格</label>
              <div className="grid grid-cols-3 gap-2">
                {FRAME_STYLES.map(s => (
                  <button
                    key={s.id}
                    onClick={() => setStyle(s)}
                    className={`p-2 rounded-lg text-xs font-bold border transition ${style.id === s.id ? 'border-white bg-white/10' : 'border-transparent bg-slate-800'}`}
                    style={{ color: s.accentColor }}
                  >
                    {s.name}
                  </button>
                ))}
              </div>
            </div>
          </section>

          {/* Image Upload & Controls */}
          <section className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
            <h2 className="text-lg font-bold mb-4 flex items-center text-purple-400">
              <span className="mr-2">🖼️</span> 角色圖片
            </h2>
            <div className="space-y-4">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageUpload}
                className="w-full text-sm text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-600 file:text-white hover:file:bg-blue-500 cursor-pointer"
              />

              {image && (
                <div className="grid grid-cols-2 gap-4 mt-4">
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">放大倍率 (Zoom)</label>
                    <input
                      type="range"
                      min="0.1"
                      max="5"
                      step="0.1"
                      value={transform.scale}
                      onChange={(e) => setTransform(prev => ({ ...prev, scale: parseFloat(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">旋轉 (Rotate)</label>
                    <input
                      type="range"
                      min="-180"
                      max="180"
                      value={transform.rotate}
                      onChange={(e) => setTransform(prev => ({ ...prev, rotate: parseInt(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">水平位移 (X)</label>
                    <input
                      type="range"
                      min="-500"
                      max="500"
                      value={transform.x}
                      onChange={(e) => setTransform(prev => ({ ...prev, x: parseInt(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">垂直位移 (Y)</label>
                    <input
                      type="range"
                      min="-500"
                      max="500"
                      value={transform.y}
                      onChange={(e) => setTransform(prev => ({ ...prev, y: parseInt(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                </div>
              )}
            </div>
          </section>

          {/* Character Information */}
          <section className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
            <h2 className="text-lg font-bold mb-4 flex items-center text-emerald-400">
              <span className="mr-2">📝</span> 基本資訊
            </h2>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs text-slate-500">姓名</label>
                <input
                  type="text"
                  placeholder="角色全名"
                  value={info.name}
                  onChange={(e) => updateInfo('name', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">伺服器</label>
                <input
                  type="text"
                  placeholder="Server Name"
                  value={info.server}
                  onChange={(e) => updateInfo('server', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">種族</label>
                <select
                  value={info.race}
                  onChange={(e) => updateInfo('race', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                >
                  <option value="">選擇種族</option>
                  {RACES.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">職業</label>
                <select
                  value={info.job}
                  onChange={(e) => updateInfo('job', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                >
                  <option value="">選擇主職業</option>
                  {JOBS.map(j => <option key={j} value={j}>{j}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">性別</label>
                <input
                  type="text"
                  placeholder="男 / 女 / 其他"
                  value={info.gender}
                  onChange={(e) => updateInfo('gender', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">歲數</label>
                <input
                  type="text"
