import React, { forwardRef } from 'react';
import { CharacterInfo, Traits, Orientation, FrameStyle, ImageTransform } from '../types';

interface CardProps {
  info: CharacterInfo;
  traits: Traits;
  orientation: Orientation;
  style: FrameStyle;
  image: string | null;
  transform: ImageTransform;
  id?: string;
}

const Card = forwardRef<HTMLDivElement, CardProps>(({ info, traits, orientation, style, image, transform, id }, ref) => {
  const isPortrait = orientation === 'portrait';

  const containerStyle: React.CSSProperties = {
    width: isPortrait ? '450px' : '800px',
    height: isPortrait ? '800px' : '450px',
    background: style.bgGradient,
    border: `8px double ${style.borderColor}`,
    position: 'relative',
    overflow: 'hidden',
    boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5)',
    transition: 'all 0.3s ease'
  };

  const imageContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: isPortrait ? '100%' : '50%',
    height: isPortrait ? '50%' : '100%',
    overflow: 'hidden',
    borderBottom: isPortrait ? `4px solid ${style.borderColor}` : 'none',
    borderRight: !isPortrait ? `4px solid ${style.borderColor}` : 'none',
    backgroundColor: '#000'
  };

  const contentContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: isPortrait ? '50%' : 0,
    left: isPortrait ? 0 : '50%',
    width: isPortrait ? '100%' : '50%',
    height: isPortrait ? '50%' : '100%',
    padding: '1.5rem',
    overflowY: 'auto',
    color: style.textColor,
    display: 'flex',
    flexDirection: 'column',
    gap: '0.75rem',
    scrollbarWidth: 'none', // For Firefox
  };

  const TraitBar = ({ label, value, left, right }: { label: string, value: number, left: string, right: string }) => {
    // 預設 50 (中間值) 視為未特別設定，若要強制顯示可移除此判斷
    if (value === 50) return null; 

    const steps = [0, 25, 50, 75, 100];

    return (
      <div className="flex flex-col gap-1 mb-1">
        <div className="flex justify-between items-center">
          <span className="text-[9px] font-bold uppercase tracking-wider opacity-40">{label}</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-[10px] opacity-70 w-12 text-right truncate">{left}</span>
          <div className="flex gap-1.5 items-center justify-center flex-1">
            {steps.map((step) => (
              <div 
                key={step}
                className={`w-2 h-2 rounded-full transition-all duration-300 ${
                  value === step 
                    ? 'bg-current scale-125 shadow-[0_0_6px_rgba(255,255,255,0.6)]' 
                    : 'bg-current opacity-10 border border-white/5'
                }`}
              />
            ))}
          </div>
          <span className="text-[10px] opacity-70 w-12 text-left truncate">{right}</span>
        </div>
      </div>
    );
  };

  return (
    <div id={id} ref={ref} style={containerStyle} className="ff-font select-none">
      <style>{`
        .card-content-scroll::-webkit-scrollbar {
          display: none;
        }
      `}</style>

      {/* Character Image */}
      <div style={imageContainerStyle}>
        {image ? (
          <img
            src={image}
            alt="Character"
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) rotate(${transform.rotate}deg)`,
              transformOrigin: 'center center'
            }}
          />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 bg-slate-900/50">
             <span className="text-4xl mb-2">👤</span>
             <p className="text-sm">尚未上傳角色圖片</p>
          </div>
        )}

        {/* Overlay Info */}
        <div className="absolute bottom-0 left-0 w-full p-4 bg-gradient-to-t from-black/80 to-transparent">
          <h1 className="text-2xl font-bold tracking-tight drop-shadow-md">{info.name || '角色姓名'}</h1>
          <p className="text-xs opacity-80 tracking-widest">{info.server || 'SERVER NAME'}</p>
        </div>
      </div>

      {/* Profile Details */}
      <div style={contentContainerStyle} className="card-content-scroll">
        {/* Basic Stats Grid */}
        <div className="grid grid-cols-2 gap-x-4 gap-y-1.5 text-xs border-b border-white/10 pb-3">
          {info.race && <div><span className="opacity-50 mr-2">種族</span>{info.race}</div>}
          {info.gender && <div><span className="opacity-50 mr-2">性別</span>{info.gender}</div>}
          {info.job && <div><span className="opacity-50 mr-2">職業</span>{info.job}</div>}
          {info.age && <div><span className="opacity-50 mr-2">歲數</span>{info.age}</div>}
          {info.height && <div><span className="opacity-50 mr-2">身高</span>{info.height}</div>}
          {info.orientation && <div><span className="opacity-50 mr-2">性向</span>{info.orientation}</div>}
          {info.birthplace && <div><span className="opacity-50 mr-2">出生地</span>{info.birthplace}</div>}
        </div>

        {/* Text Sections */}
        {info.personality && (
          <div className="space-y-1">
            <h3 className="text-[9px] font-bold uppercase tracking-widest opacity-40">性格描述 Personality</h3>
            <p className="text-xs leading-relaxed italic opacity-90">{info.personality}</p>
          </div>
        )}

        {info.background && (
          <div className="space-y-1">
            <h3 className="text-[9px] font-bold uppercase tracking-widest opacity-40">背景故事 Background</h3>
            <p className="text-[11px] leading-relaxed opacity-90">{info.background}</p>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          {info.likes && (
             <div className="space-y-1">
                <h3 className="text-[9px] font-bold uppercase tracking-widest opacity-40 text-green-400/70">喜歡 Likes</h3>
                <p className="text-[10px] leading-snug">{info.likes}</p>
             </div>
          )}
          {info.dislikes && (
             <div className="space-y-1">
                <h3 className="text-[9px] font-bold uppercase tracking-widest opacity-40 text-red-400/70">討厭 Dislikes</h3>
                <p className="text-[10px] leading-snug">{info.dislikes}</p>
             </div>
          )}
        </div>

        {/* Trait Circles Section */}
        <div className="grid grid-cols-1 gap-y-2 pt-2 border-t border-white/10">
          <TraitBar label="體型 Muscles" value={traits.muscles} left="纖細" right="健壯" />
          <TraitBar label="體溫 Temperature" value={traits.temperature} left="較低" right="較高" />
          <TraitBar label="聲量 Voice" value={traits.voiceVolume} left="小聲" right="大聲" />
          <TraitBar label="感性 Sensitivity" value={traits.sensitivity} left="冷淡" right="豐沛" />
          <TraitBar label="食量 Appetite" value={traits.appetite} left="小鳥胃" right="大胃王" />
          <TraitBar label="酒量 Alcohol" value={traits.alcoholTolerance} left="不太好" right="很好" />
          <TraitBar label="運動 Athleticism" value={traits.athleticism} left="不太好" right="很好" />
          <TraitBar label="戰鬥範圍 Combat" value={traits.combatRange} left="遠程" right="近戰" />
          <TraitBar label="戰鬥喜好 Preference" value={traits.combatPref} left="討厭" right="喜歡" />
        </div>
      </div>

      {/* Decorative Frame Elements */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
      <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 pointer-events-none" style={{ borderColor: style.accentColor }} />
    </div>
  );
});

export default Card;

