import React, { useState, useRef, useEffect, useMemo } from 'react';
import Card from './components/Card';
import TraitSelector from './components/SliderInput'; // Keep the import path for simplicity in this update
import { CharacterInfo, Traits, Orientation, ImageTransform, FrameStyle } from './types';
import { FRAME_STYLES, JOBS, RACES } from './constants';
import { improveDescription } from './services/geminiService';

const initialInfo: CharacterInfo = {
  name: '',
  server: '',
  gender: '',
  race: '',
  age: '',
  height: '',
  orientation: '',
  job: '',
  personality: '',
  background: '',
  birthplace: '',
  likes: '',
  dislikes: '',
};

const initialTraits: Traits = {
  muscles: 50,
  temperature: 50,
  voiceVolume: 50,
  voicePitch: 50,
  sensitivity: 50,
  appetite: 50,
  tableManners: 50,
  alcoholPref: 50,
  alcoholTolerance: 50,
  athleticism: 50,
  combatPref: 50,
  combatSkill: 50,
  combatRange: 50,
};

const initialTransform: ImageTransform = {
  x: 0,
  y: 0,
  scale: 1,
  rotate: 0,
};

const MAX_ACTIVE_TRAITS = 6;

const App: React.FC = () => {
  const [info, setInfo] = useState<CharacterInfo>(initialInfo);
  const [traits, setTraits] = useState<Traits>(initialTraits);
  const [orientation, setOrientation] = useState<Orientation>('portrait');
  const [style, setStyle] = useState<FrameStyle>(FRAME_STYLES[0]);
  const [image, setImage] = useState<string | null>(null);
  const [transform, setTransform] = useState<ImageTransform>(initialTransform);
  const [isImproving, setIsImproving] = useState(false);
  const [previewScale, setPreviewScale] = useState(1);

  const cardRef = useRef<HTMLDivElement>(null);
  const previewContainerRef = useRef<HTMLDivElement>(null);

  // Calculate how many traits are currently active (not at 50)
  const activeTraitsCount = useMemo(() => {
    return Object.values(traits).filter(v => v !== 50).length;
  }, [traits]);

  // Auto-scale the preview to fit the container width
  useEffect(() => {
    const handleResize = () => {
      if (previewContainerRef.current) {
        const containerWidth = previewContainerRef.current.offsetWidth - 48; // padding
        const cardWidth = orientation === 'landscape' ? 800 : 450;
        if (containerWidth < cardWidth) {
          setPreviewScale(containerWidth / cardWidth);
        } else {
          setPreviewScale(1);
        }
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [orientation]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImage(event.target?.result as string);
        setTransform(initialTransform);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleExport = async () => {
    if (cardRef.current) {
      const canvas = await (window as any).html2canvas(cardRef.current, {
        useCORS: true,
        backgroundColor: null,
        scale: 2 // Higher resolution
      });
      const link = document.createElement('a');
      link.download = `FF14_CharacterCard_${info.name || 'Export'}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  const updateInfo = (field: keyof CharacterInfo, value: string) => {
    setInfo(prev => ({ ...prev, [field]: value }));
  };

  const updateTrait = (field: keyof Traits, value: number) => {
    // If we're at the limit and trying to activate a new trait (value not 50), ignore it
    const isActivatingNew = traits[field] === 50 && value !== 50;
    if (isActivatingNew && activeTraitsCount >= MAX_ACTIVE_TRAITS) {
      return;
    }
    setTraits(prev => ({ ...prev, [field]: value }));
  };

  const handleImproveText = async (type: 'personality' | 'background') => {
    setIsImproving(true);
    const improved = await improveDescription(info[type], type);
    updateInfo(type, improved);
    setIsImproving(false);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 p-4 sticky top-0 z-50 shadow-xl">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-xl shadow-lg shadow-blue-500/20">C</div>
            <h1 className="text-xl font-bold tracking-tight ff-font">Eorzea Card Maker</h1>
          </div>
          <button
            onClick={handleExport}
            className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-full font-bold transition shadow-lg shadow-blue-600/30 flex items-center space-x-2"
          >
            <span>💾 儲存卡片</span>
          </button>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto p-4 lg:p-10 grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20">

        {/* Left Column: Editor Controls */}
        <div className="lg:col-span-5 xl:col-span-4 space-y-8 pb-20">

          {/* Card Config */}
          <section className="bg-slate-900 rounded-2xl p-6 border border-slate-800 shadow-inner">
            <h2 className="text-lg font-bold mb-4 flex items-center text-blue-400">
              <span className="mr-2">🎴</span> 基本設定
            </h2>
            <div className="grid grid-cols-2 gap-4 mb-6">
              <button
                onClick={() => setOrientation('portrait')}
                className={`p-3 rounded-xl border-2 transition ${orientation === 'portrait' ? 'border-blue-500 bg-blue-500/10' : 'border-slate-800 bg-slate-800/50'}`}
              >
                直式 Portrait
              </button>
              <button
                onClick={() => setOrientation('landscape')}
                className={`p-3 rounded-xl border-2 transition ${orientation === 'landscape' ? 'border-blue-500 bg-blue-500/10' : 'border-slate-800 bg-slate-800/50'}`}
              >
                橫式 Landscape
              </button>
            </div>

            <div className="space-y-4">
              <label className="block text-sm font-medium text-slate-400">框架風格</label>
              <div className="grid grid-cols-3 gap-2">
                {FRAME_STYLES.map(s => (
                  <button
                    key={s.id}
                    onClick={() => setStyle(s)}
                    className={`p-2 rounded-lg text-xs font-bold border transition ${style.id === s.id ? 'border-white bg-white/10' : 'border-transparent bg-slate-800'}`}
                    style={{ color: s.accentColor }}
                  >
                    {s.name}
                  </button>
                ))}
              </div>
            </div>
          </section>

          {/* Image Upload & Controls */}
          <section className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
            <h2 className="text-lg font-bold mb-4 flex items-center text-purple-400">
              <span className="mr-2">🖼️</span> 角色圖片
            </h2>
            <div className="space-y-4">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageUpload}
                className="w-full text-sm text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-600 file:text-white hover:file:bg-blue-500 cursor-pointer"
              />

              {image && (
                <div className="grid grid-cols-2 gap-4 mt-4">
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">放大倍率 (Zoom)</label>
                    <input
                      type="range"
                      min="0.1"
                      max="5"
                      step="0.1"
                      value={transform.scale}
                      onChange={(e) => setTransform(prev => ({ ...prev, scale: parseFloat(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">旋轉 (Rotate)</label>
                    <input
                      type="range"
                      min="-180"
                      max="180"
                      value={transform.rotate}
                      onChange={(e) => setTransform(prev => ({ ...prev, rotate: parseInt(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">水平位移 (X)</label>
                    <input
                      type="range"
                      min="-500"
                      max="500"
                      value={transform.x}
                      onChange={(e) => setTransform(prev => ({ ...prev, x: parseInt(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">垂直位移 (Y)</label>
                    <input
                      type="range"
                      min="-500"
                      max="500"
                      value={transform.y}
                      onChange={(e) => setTransform(prev => ({ ...prev, y: parseInt(e.target.value) }))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                    />
                  </div>
                </div>
              )}
            </div>
          </section>

          {/* Character Information */}
          <section className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
            <h2 className="text-lg font-bold mb-4 flex items-center text-emerald-400">
              <span className="mr-2">📝</span> 基本資訊
            </h2>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs text-slate-500">姓名</label>
                <input
                  type="text"
                  placeholder="角色全名"
                  value={info.name}
                  onChange={(e) => updateInfo('name', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">伺服器</label>
                <input
                  type="text"
                  placeholder="Server Name"
                  value={info.server}
                  onChange={(e) => updateInfo('server', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">種族</label>
                <select
                  value={info.race}
                  onChange={(e) => updateInfo('race', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                >
                  <option value="">選擇種族</option>
                  {RACES.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">職業</label>
                <select
                  value={info.job}
                  onChange={(e) => updateInfo('job', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                >
                  <option value="">選擇主職業</option>
                  {JOBS.map(j => <option key={j} value={j}>{j}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">性別</label>
                <input
                  type="text"
                  placeholder="男 / 女 / 其他"
                  value={info.gender}
                  onChange={(e) => updateInfo('gender', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">歲數</label>
                <input
                  type="text"
