              <div className="space-y-1">
                <label className="text-xs text-slate-500">身高 (cm)</label>
                <input
                  type="text"
                  placeholder="175"
                  value={info.height}
                  onChange={(e) => updateInfo('height', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">性向</label>
                <input
                  type="text"
                  placeholder="例如：異性戀 / 雙性戀"
                  value={info.orientation}
                  onChange={(e) => updateInfo('orientation', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-slate-500">出生地</label>
                <input
                  type="text"
                  placeholder="例如：格里達尼亞"
                  value={info.birthplace}
                  onChange={(e) => updateInfo('birthplace', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                />
              </div>
            </div>

            <div className="mt-4 space-y-4">
              <div className="space-y-1">
                <div className="flex justify-between items-center">
                  <label className="text-xs text-slate-500">性格描述</label>
                  <button 
                    onClick={() => handleImproveText('personality')}
                    disabled={isImproving || !info.personality}
                    className="text-[10px] bg-slate-700 hover:bg-slate-600 px-2 py-0.5 rounded text-blue-300 disabled:opacity-50"
                  >
                    {isImproving ? '魔法處理中...' : '✨ AI 潤飾'}
                  </button>
                </div>
                <textarea
                  placeholder="描述你的角色性格..."
                  rows={3}
                  value={info.personality}
                  onChange={(e) => updateInfo('personality', e.target.value)}
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none resize-none"
                />
              </div>

              <div className="space-y-1">
                <div className="flex justify-between items-center">
                  <label className="text-xs text-slate-500">背景故事</label>
                  <button 
                    onClick={() => handleImproveText('background')}
                    disabled={isImproving || !info.background}
                    className="text-[10px] bg-slate-700 hover:bg-slate-600 px-2 py-0.5 rounded text-blue-300 disabled:opacity-50"
                  >
                    {isImproving ? '魔法處理中...' : '✨ AI 潤飾'}
                  </button>
                </div>
                <textarea
                  placeholder="分享角色的過去..."
                  rows={4}
                  value={info.background}
                  onChange={(e) => updateInfo('background', e.target.value)}
