import React, { useState, useRef, useEffect, useMemo } from 'react';
import Card from './components/Card';
import TraitSelector from './components/SliderInput';
import { CharacterInfo, Traits, Orientation, ImageTransform, FrameStyle, BorderStyle } from './types';
import { FRAME_STYLES, JOBS, RACES, FONT_OPTIONS, BORDER_TYPES } from './constants';
import { improveDescription } from './services/geminiService';

const initialInfo: CharacterInfo = {
  name: '',
  server: '',
  gender: '',
  race: '',
  age: '',
  height: '',
  orientation: '',
  job: '',
  personality: '',
  background: '',
  birthplace: '',
  likes: '',
  dislikes: '',
  selectedFont: FONT_OPTIONS[0].family,
  customBorderColor: FRAME_STYLES[0].borderColor,
  customBgStart: FRAME_STYLES[0].bgStart,
  customBgEnd: FRAME_STYLES[0].bgEnd,
  customTextColor: FRAME_STYLES[0].textColor,
  customAccentColor: FRAME_STYLES[0].accentColor,
  customBorderStyle: 'solid',
  customBorderWidth: 4
};

const initialTraits: Traits = {
  muscles: 50,
  temperature: 50,
  voiceVolume: 50,
  voicePitch: 50,
  sensitivity: 50,
  appetite: 50,
  tableManners: 50,
  alcoholPref: 50,
  alcoholTolerance: 50,
  athleticism: 50,
  combatPref: 50,
  combatSkill: 50,
  combatRange: 50,
};

const initialTransform: ImageTransform = {
  x: 0,
  y: 0,
  scale: 1,
  rotate: 0,
};

const MAX_ACTIVE_TRAITS = 6;
const LIMITS = {
  personality: 120,
  background: 350
};

const App: React.FC = () => {
  const [info, setInfo] = useState<CharacterInfo>(initialInfo);
  const [traits, setTraits] = useState<Traits>(initialTraits);
  const [orientation, setOrientation] = useState<Orientation>('portrait');
  const [style, setStyle] = useState<FrameStyle>(FRAME_STYLES[0]);
  const [image, setImage] = useState<string | null>(null);
  const [transform, setTransform] = useState<ImageTransform>(initialTransform);
  const [isImproving, setIsImproving] = useState(false);
  const [previewScale, setPreviewScale] = useState(1);

  const cardRef = useRef<HTMLDivElement>(null);
  const previewContainerRef = useRef<HTMLDivElement>(null);

  const activeTraitsCount = useMemo(() => {
    return Object.values(traits).filter(v => v !== 50).length;
  }, [traits]);

  useEffect(() => {
    const handleResize = () => {
      if (previewContainerRef.current) {
        const containerWidth = previewContainerRef.current.offsetWidth - 48;
        const cardWidth = orientation === 'landscape' ? 800 : 450;
        if (containerWidth < cardWidth) {
          setPreviewScale(containerWidth / cardWidth);
        } else {
          setPreviewScale(1);
        }
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [orientation]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImage(event.target?.result as string);
        setTransform(initialTransform);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleExport = async () => {
    if (cardRef.current) {
      const canvas = await (window as any).html2canvas(cardRef.current, {
        useCORS: true,
        backgroundColor: null,
        scale: 2
      });
      const link = document.createElement('a');
      link.download = `FF14_TechCard_${info.name || 'Export'}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  const updateInfo = (field: keyof CharacterInfo, value: any) => {
    setInfo(prev => ({ ...prev, [field]: value }));
  };

  const selectPresetStyle = (s: FrameStyle) => {
    setStyle(s);
    setInfo(prev => ({
      ...prev,
      customBorderColor: s.borderColor,
      customBgStart: s.bgStart,
      customBgEnd: s.bgEnd,
      customTextColor: s.textColor,
      customAccentColor: s.accentColor,
    }));
  };

  const updateTrait = (field: keyof Traits, value: number) => {
    const isActivatingNew = traits[field] === 50 && value !== 50;
    if (isActivatingNew && activeTraitsCount >= MAX_ACTIVE_TRAITS) {
      return;
    }
    setTraits(prev => ({ ...prev, [field]: value }));
  };

  const handleImproveText = async (type: 'personality' | 'background') => {
    setIsImproving(true);
    const improved = await improveDescription(info[type], type);
    const limit = LIMITS[type];
    const finalResult = improved.length > limit ? improved.substring(0, limit) : improved;
    updateInfo(type, finalResult);
    setIsImproving(false);
  };

  const CharacterCounter = ({ current, max }: { current: number, max: number }) => {
    const isOver = current >= max;
    return (
      <div className={`text-[10px] text-right mt-1 font-mono ${isOver ? 'text-red-400' : 'text-slate-500'}`}>
        [{current.toString().padStart(3, '0')} / {max}]
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-transparent relative z-10">
      {/* Tech Header */}
      <header className="bg-slate-900/80 border-b border-cyan-500/30 p-4 sticky top-0 z-50 backdrop-blur-md shadow-[0_0_20px_rgba(0,242,255,0.1)]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <div className="w-12 h-12 border-2 border-cyan-400 bg-cyan-950 rounded-lg flex items-center justify-center font-bold text-2xl text-cyan-400 shadow-[0_0_15px_rgba(0,242,255,0.4)] tech-font animate-pulse">
              Ξ
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-widest tech-font text-white">EORZEA_CARD_MAKER</h1>
              <p className="text-[10px] text-cyan-500 font-mono tracking-tighter uppercase">Initializing secure connection... v3.1.0</p>
            </div>
          </div>
          <button
            onClick={handleExport}
            className="group relative px-8 py-2 overflow-hidden bg-transparent border border-cyan-400 text-cyan-400 rounded-sm font-bold tech-font hover:bg-cyan-400 hover:text-black transition-all duration-300 shadow-[0_0_10px_rgba(0,242,255,0.2)]"
          >
            <span className="relative z-10 flex items-center gap-2">
               <span className="text-xs">DOWNLOAD_DATA</span>
            </span>
            <div className="absolute inset-0 bg-cyan-400 -translate-x-full group-hover:translate-x-0 transition-transform duration-300 z-0"></div>
          </button>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto p-4 lg:p-10 grid grid-cols-1 lg:grid-cols-12 gap-10">

        {/* Sidebar Controls */}
        <div className="lg:col-span-4 xl:col-span-4 space-y-6 pb-20">

          <section className="bg-slate-900/60 rounded-lg p-6 border-l-4 border-cyan-500 shadow-xl backdrop-blur-sm">
            <h2 className="text-sm font-bold mb-4 flex items-center text-cyan-400 tech-font tracking-widest uppercase border-b border-cyan-900/50 pb-2">
              <span className="mr-2">■</span> SYSTEM_CONFIGURATION
            </h2>

            <div className="grid grid-cols-2 gap-2 mb-6">
              {['portrait', 'landscape'].map((o) => (
                <button
                  key={o}
                  onClick={() => setOrientation(o as any)}
                  className={`py-2 text-[10px] tech-font border transition-all ${orientation === o ? 'bg-cyan-500 text-black border-cyan-400' : 'bg-slate-800/50 text-slate-500 border-slate-700 hover:border-cyan-700'}`}
                >
                  {o.toUpperCase()}
                </button>
              ))}
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] text-slate-500 tech-font">PRESET_SKINS</label>
                <div className="grid grid-cols-2 gap-2">
                  {FRAME_STYLES.map(s => (
                    <button
                      key={s.id}
                      onClick={() => selectPresetStyle(s)}
                      className={`p-2 rounded-sm text-[10px] tech-font border transition-all truncate ${style.id === s.id ? 'bg-slate-700 border-white text-white' : 'bg-slate-950/80 border-slate-800 text-slate-400'}`}
                    >
                      {s.name}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] text-slate-500 tech-font">INTERFACE_FONT</label>
                <div className="grid grid-cols-2 gap-2">
                  {FONT_OPTIONS.map(font => (
                    <button
                      key={font.id}
                      onClick={() => updateInfo('selectedFont', font.family)}
                      style={{ fontFamily: font.family }}
                      className={`p-2 text-[10px] border transition-all ${info.selectedFont === font.family ? 'bg-cyan-500/20 border-cyan-400 text-cyan-200' : 'bg-slate-950/80 border-slate-800 text-slate-500'}`}
                    >
                      {font.name}
                    </button>
                  ))}
                </div>
              </div>

              <div className="pt-4 border-t border-slate-800 space-y-4">
                <h3 className="text-[10px] tech-font text-cyan-400/80">ADVANCED_ADJUSTMENTS</h3>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[9px] text-slate-500 tech-font">BORDER_TYPE</label>
                    <select
                      value={info.customBorderStyle}
                      onChange={(e) => updateInfo('customBorderStyle', e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 rounded p-2 text-[10px] text-cyan-200 focus:border-cyan-500 outline-none tech-font"
                    >
                      {BORDER_TYPES.map(bt => <option key={bt.id} value={bt.id}>{bt.name.toUpperCase()}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] text-slate-500 tech-font">THICKNESS</label>
                    <input
                      type="range"
                      min="1"
                      max="16"
                      value={info.customBorderWidth}
                      onChange={(e) => updateInfo('customBorderWidth', parseInt(e.target.value))}
                      className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-y-3">
                   {[
                     { field: 'customBorderColor', label: 'BORDER_CLR' },
                     { field: 'customTextColor', label: 'TEXT_CLR' },
