            <div className="space-y-1">
              {[
                { label: 'MUSCLE_DENSITY', field: 'muscles', l: 'SLIGHT', r: 'ROBUST' },
                { label: 'CORE_TEMP', field: 'temperature', l: 'LOW', r: 'HIGH' },
