import React from 'react';

interface TraitSelectorProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  leftLabel: string;
  rightLabel: string;
}

const TraitSelector: React.FC<TraitSelectorProps> = ({ label, value, onChange, leftLabel, rightLabel }) => {
  const steps = [0, 25, 50, 75, 100];

  return (
    <div className="flex flex-col space-y-2 mb-4 group">
      <div className="flex justify-between items-center">
        <label className="text-[9px] font-bold text-slate-400 tech-font tracking-widest">{label}</label>
      </div>

      <div className="flex items-center justify-between bg-black/40 p-2 rounded border border-slate-800 transition-colors group-hover:border-amber-900/50">
        <span className="text-[8px] w-12 text-right text-slate-600 tech-font leading-tight pr-1 uppercase">{leftLabel}</span>

        <div className="flex items-center justify-between flex-1 px-4 relative">
          {/* Connector Line with glow */}
          <div className="absolute top-1/2 left-4 right-4 h-[2px] bg-slate-900 -translate-y-1/2 z-0"></div>

          {steps.map((step) => (
            <button
              key={step}
              onClick={() => onChange(step)}
              className={`relative z-10 w-2 h-2 transition-all duration-300 transform ${
                value === step 
                  ? 'bg-amber-400 scale-150 rotate-45 shadow-[0_0_12px_#fbbf24]' 
                  : 'bg-slate-800 hover:bg-slate-600'
              }`}
              title={`${step}%`}
            />
          ))}
        </div>

        <span className="text-[8px] w-12 text-left text-slate-600 tech-font leading-tight pl-1 uppercase">{rightLabel}</span>
      </div>
    </div>
  );
};

export default TraitSelector;

import React, { forwardRef } from 'react';
import { CharacterInfo, Traits, Orientation, FrameStyle, ImageTransform } from '../types';

interface CardProps {
  info: CharacterInfo;
  traits: Traits;
  orientation: Orientation;
  style: FrameStyle;
  image: string | null;
  transform: ImageTransform;
  id?: string;
}

const Card = forwardRef<HTMLDivElement, CardProps>(({ info, traits, orientation, style, image, transform, id }, ref) => {
  const isPortrait = orientation === 'portrait';

  // Use custom style if available, otherwise use frame style defaults
  const borderColor = info.customBorderColor || style.borderColor;
  const bgStart = info.customBgStart || style.bgStart;
  const bgEnd = info.customBgEnd || style.bgEnd;
  const textColor = info.customTextColor || style.textColor;
  const accentColor = info.customAccentColor || style.accentColor;
  const borderStyle = info.customBorderStyle || 'solid';
  const borderWidth = info.customBorderWidth !== undefined ? info.customBorderWidth : 4;

  const containerStyle: React.CSSProperties = {
    width: isPortrait ? '450px' : '800px',
    height: isPortrait ? '800px' : '450px',
    background: `linear-gradient(135deg, ${bgStart} 0%, ${bgEnd} 100%)`,
    border: `${borderWidth}px ${borderStyle} ${borderColor}`,
    position: 'relative',
    overflow: 'hidden',
    boxShadow: `0 0 30px ${borderColor}33`,
    transition: 'all 0.5s cubic-bezier(0.16, 1, 0.3, 1)',
    fontFamily: info.selectedFont || 'inherit'
  };

  const imageContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: isPortrait ? '100%' : '50%',
    height: isPortrait ? '50%' : '100%',
    overflow: 'hidden',
    borderBottom: isPortrait ? `2px solid ${borderColor}55` : 'none',
    borderRight: !isPortrait ? `2px solid ${borderColor}55` : 'none',
    backgroundColor: '#000'
  };

  const contentContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: isPortrait ? '50%' : 0,
    left: isPortrait ? 0 : '50%',
    width: isPortrait ? '100%' : '50%',
    height: isPortrait ? '50%' : '100%',
    padding: '1.5rem',
    overflowY: 'auto',
    color: textColor,
    display: 'flex',
    flexDirection: 'column',
    gap: '0.75rem',
    scrollbarWidth: 'none',
  };

  const TraitBar = ({ label, value, left, right }: { label: string, value: number, left: string, right: string }) => {
    if (value === 50) return null; 
    const steps = [0, 25, 50, 75, 100];

    return (
      <div className="flex flex-col gap-1.5 mb-2">
        <div className="flex justify-between items-center">
          <span className="text-[8px] font-bold uppercase tracking-wider opacity-40">{label}</span>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-[9px] opacity-60 w-16 text-right truncate leading-none uppercase">{left}</span>
          <div className="flex gap-1.5 items-center justify-center flex-1">
            {steps.map((step) => (
              <div 
                key={step}
                className={`w-2 h-2 transition-all duration-300 ${
                  value === step 
                    ? 'scale-125 shadow-[0_0_8px_rgba(255,255,255,0.7)]' 
                    : 'opacity-10'
                }`}
                style={{ backgroundColor: value === step ? accentColor : 'currentColor', borderRadius: '1px' }}
              />
            ))}
          </div>
          <span className="text-[9px] opacity-60 w-16 text-left truncate leading-none uppercase">{right}</span>
        </div>
      </div>
    );
  };

  return (
    <div id={id} ref={ref} style={containerStyle} className="select-none">
      <style>{`
        .card-content-scroll::-webkit-scrollbar { display: none; }
      `}</style>

      {/* Visual Glitch Decorators */}
      <div className="absolute top-2 right-2 flex flex-col gap-1 opacity-20">
         <div className="w-8 h-[1px] bg-white"></div>
         <div className="w-4 h-[1px] bg-white self-end"></div>
      </div>

      <div style={imageContainerStyle}>
        {image ? (
          <img
            src={image}
            alt="Character"
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) rotate(${transform.rotate}deg)`,
              transformOrigin: 'center center'
            }}
          />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center text-slate-700 bg-slate-950">
             <span className="text-4xl mb-2 opacity-20">IDENTITY_MISSING</span>
             <p className="text-[10px] font-mono tracking-widest uppercase opacity-40">Awaiting visual data...</p>
          </div>
        )}

        {/* Identity Label Overlay */}
        <div className="absolute bottom-0 left-0 w-full p-4 bg-gradient-to-t from-black to-transparent">
          <div className="flex flex-col">
            <h1 className="text-2xl font-bold tracking-[0.1em] drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] uppercase">{info.name || 'ANONYMOUS_UNIT'}</h1>
            <div className="flex items-center gap-2 mt-1">
               <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
               <p className="text-[9px] opacity-80 tracking-widest font-mono">{info.server || 'NODE_UNKNOWN'}</p>
            </div>
          </div>
        </div>
      </div>

      <div style={contentContainerStyle} className="card-content-scroll">
        <div className="grid grid-cols-2 gap-x-4 gap-y-1.5 text-[10px] border-b border-white/5 pb-3 font-mono">
          {[
            { label: 'RACE', val: info.race },
            { label: 'SEX', val: info.gender },
            { label: 'CLASS', val: info.job },
            { label: 'CYCLE', val: info.age },
            { label: 'SCALE', val: info.height },
            { label: 'PATH', val: info.orientation },
            { label: 'ORIGIN', val: info.birthplace }
          ].map(item => item.val && (
            <div key={item.label} className="flex gap-2">
              <span className="opacity-30 font-bold">{item.label}:</span>
              <span className="truncate">{item.val}</span>
            </div>
          ))}
        </div>

        {info.personality && (
          <div className="space-y-1">
            <h3 className="text-[8px] font-bold uppercase tracking-widest opacity-30 tech-font">COG_PATTERNS //</h3>
            <p className="text-[11px] leading-relaxed italic opacity-80">{info.personality}</p>
          </div>
        )}

        {info.background && (
          <div className="space-y-1">
            <h3 className="text-[8px] font-bold uppercase tracking-widest opacity-30 tech-font">HISTORICAL_LOG //</h3>
            <p className="text-[10px] leading-relaxed opacity-70 border-l border-white/10 pl-3">{info.background}</p>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          {info.likes && (
             <div className="space-y-1">
                <h3 className="text-[8px] font-bold uppercase tracking-widest opacity-30 text-emerald-500/70 tech-font">AFFINITIES+</h3>
                <p className="text-[10px] leading-snug">{info.likes}</p>
             </div>
          )}
          {info.dislikes && (
             <div className="space-y-1">
                <h3 className="text-[8px] font-bold uppercase tracking-widest opacity-30 text-rose-500/70 tech-font">AVERSIONS-</h3>
                <p className="text-[10px] leading-snug">{info.dislikes}</p>
             </div>
          )}
        </div>

        <div className="grid grid-cols-1 gap-y-0.5 pt-3 border-t border-white/5">
          <TraitBar label="MUSCLE_DENSITY" value={traits.muscles} left="Slight" right="Robust" />
          <TraitBar label="CORE_TEMPERATURE" value={traits.temperature} left="Low" right="High" />
          <TraitBar label="VOICE_VOLUME" value={traits.voiceVolume} left="Soft" right="Loud" />
          <TraitBar label="COG_SENSITIVITY" value={traits.sensitivity} left="Cold" right="Warm" />
          <TraitBar label="CONSUMPTION_RATE" value={traits.appetite} left="Petit" right="Large" />
          <TraitBar label="ALCOHOL_RESISTANCE" value={traits.alcoholTolerance} left="Weak" right="Strong" />
          <TraitBar label="KINETIC_ENERGY" value={traits.athleticism} left="Weak" right="Excellent" />
          <TraitBar label="ENGAGEMENT_RANGE" value={traits.combatRange} left="Ranged" right="Melee" />
          <TraitBar label="COMBAT_AFFINITY" value={traits.combatPref} left="Avoid" right="Enjoy" />
        </div>
      </div>

      {/* Futuristic Corner Brackets */}
      <div className="absolute top-0 left-0 w-6 h-6 border-t-2 border-l-2 pointer-events-none" style={{ borderColor: accentColor }} />
      <div className="absolute top-0 right-0 w-6 h-6 border-t-2 border-r-2 pointer-events-none" style={{ borderColor: accentColor }} />
      <div className="absolute bottom-0 left-0 w-6 h-6 border-b-2 border-l-2 pointer-events-none" style={{ borderColor: accentColor }} />
      <div className="absolute bottom-0 right-0 w-6 h-6 border-b-2 border-r-2 pointer-events-none" style={{ borderColor: accentColor }} />
    </div>
  );
});

export default Card;

