import React, { forwardRef } from 'react';
import { CharacterInfo, Traits, Orientation, FrameStyle, ImageTransform } from '../types';

interface CardProps {
  info: CharacterInfo;
  traits: Traits;
  orientation: Orientation;
  style: FrameStyle;
  image: string | null;
  transform: ImageTransform;
  id?: string;
}

const Card = forwardRef<HTMLDivElement, CardProps>(({ info, traits, orientation, style, image, transform, id }, ref) => {
  const isPortrait = orientation === 'portrait';

  const borderColor = info.customBorderColor || style.borderColor;
  const bgStart = info.customBgStart || style.bgStart;
  const bgEnd = info.customBgEnd || style.bgEnd;
  const textColor = info.customTextColor || style.textColor;
  const accentColor = info.customAccentColor || style.accentColor;
  const borderStyle = info.customBorderStyle || 'solid';
  const borderWidth = info.customBorderWidth !== undefined ? info.customBorderWidth : 4;

  const containerStyle: React.CSSProperties = {
    width: isPortrait ? '450px' : '800px',
    height: isPortrait ? '800px' : '450px',
    background: `linear-gradient(135deg, ${bgStart} 0%, ${bgEnd} 100%)`,
    border: `${borderWidth}px ${borderStyle} ${borderColor}`,
    position: 'relative',
    overflow: 'hidden',
    boxShadow: `0 0 30px ${borderColor}33`,
    transition: 'all 0.5s cubic-bezier(0.16, 1, 0.3, 1)',
    fontFamily: info.selectedFont || 'inherit'
  };

  // 縮小圖片佔比：直式改為 35% 高度，橫式改為 30% 寬度
  const imageContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: isPortrait ? '100%' : '30%',
    height: isPortrait ? '35%' : '100%',
    overflow: 'hidden',
    borderBottom: isPortrait ? `2px solid ${borderColor}55` : 'none',
    borderRight: !isPortrait ? `2px solid ${borderColor}55` : 'none',
    backgroundColor: '#000'
  };

  const contentContainerStyle: React.CSSProperties = {
    position: 'absolute',
    top: isPortrait ? '35%' : 0,
    left: isPortrait ? 0 : '30%',
    width: isPortrait ? '100%' : '70%',
    height: isPortrait ? '65%' : '100%',
    padding: '1.25rem',
    paddingBottom: '2.5rem', 
    overflowY: 'auto',
    color: textColor,
    display: 'flex',
    flexDirection: 'column',
    gap: '0.75rem',
    scrollbarWidth: 'none',
  };

  const TraitBar = ({ label, value, left, right }: { label: string, value: number, left: string, right: string }) => {
    if (value === 50) return null; 
    const steps = [0, 25, 50, 75, 100];

    return (
      <div className="flex flex-col gap-1 mb-1.5">
        <div className="flex justify-between items-center">
          <span className="text-[7.5px] font-bold uppercase tracking-wider opacity-40 leading-none">{label}</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-[8.5px] opacity-60 w-12 text-right truncate leading-none uppercase">{left}</span>
          <div className="flex gap-1 items-center justify-center flex-1">
            {steps.map((step) => (
              <div 
                key={step}
                className={`w-1.5 h-1.5 transition-all duration-300 ${
                  value === step 
                    ? 'scale-125 shadow-[0_0_8px_rgba(255,255,255,0.7)] opacity-100' 
                    : 'opacity-10'
                }`}
                style={{ backgroundColor: value === step ? accentColor : 'currentColor', borderRadius: '0.5px' }}
              />
            ))}
          </div>
          <span className="text-[8.5px] opacity-60 w-12 text-left truncate leading-none uppercase">{right}</span>
        </div>
      </div>
    );
  };

  return (
    <div id={id} ref={ref} style={containerStyle} className="select-none">
      <style>{`
        .card-content-scroll::-webkit-scrollbar { display: none; }
      `}</style>

      {/* 視覺裝飾 */}
      <div className="absolute top-2 right-2 flex flex-col gap-1 opacity-20">
         <div className="w-8 h-[1px] bg-white"></div>
         <div className="w-4 h-[1px] bg-white self-end"></div>
      </div>

      <div style={imageContainerStyle}>
        {image ? (
          <img
            src={image}
            alt="角色圖片"
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) rotate(${transform.rotate}deg)`,
              transformOrigin: 'center center'
            }}
          />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center text-slate-700 bg-slate-950">
             <span className="text-3xl mb-1 opacity-20">影像缺失</span>
             <p className="text-[8px] font-mono tracking-widest uppercase opacity-40 text-center px-2">等待傳輸影像數據...</p>
          </div>
        )}

        {/* 姓名與伺服器疊加層 - 在較小的圖片框中稍微調整間距 */}
        <div className="absolute bottom-0 left-0 w-full p-3 bg-gradient-to-t from-black to-transparent">
          <div className="flex flex-col">
            <h1 className="text-xl font-bold tracking-[0.05em] drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] uppercase truncate">{info.name || '未登錄個體'}</h1>
            <div className="flex items-center gap-1.5 mt-0.5">
               <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span>
               <p className="text-[8px] opacity-80 tracking-widest font-mono truncate">{info.server || '未知節點'}</p>
            </div>
          </div>
        </div>
      </div>

      <div style={contentContainerStyle} className="card-content-scroll">
        <div className="grid grid-cols-2 gap-x-3 gap-y-1 text-[9px] border-b border-white/5 pb-2 font-mono">
          {[
            { label: '種族', val: info.race },
            { label: '性別', val: info.gender },
            { label: '職業', val: info.job },
            { label: '歲數', val: info.age },
            { label: '身高', val: info.height },
            { label: '性向', val: info.orientation },
            { label: '出生', val: info.birthplace }
          ].map(item => item.val && (
            <div key={item.label} className="flex gap-1.5">
              <span className="opacity-30 font-bold whitespace-nowrap">{item.label}:</span>
              <span className="truncate">{item.val}</span>
            </div>
          ))}
        </div>

        {info.personality && (
          <div className="space-y-0.5">
            <h3 className="text-[8px] font-bold uppercase tracking-widest opacity-30 tech-font">認知模式 // 角色性格</h3>
            <p className="text-[10px] leading-snug italic opacity-85">{info.personality}</p>
          </div>
        )}

        {info.background && (
          <div className="space-y-0.5">
            <h3 className="text-[8px] font-bold uppercase tracking-widest opacity-30 tech-font">歷史紀錄 // 背景故事</h3>
            <p className="text-[9.5px] leading-snug opacity-75 border-l border-white/10 pl-2.5">{info.background}</p>
          </div>
        )}

        <div className="grid grid-cols-2 gap-3">
          {info.likes && (
             <div className="space-y-0.5">
                <h3 className="text-[7.5px] font-bold uppercase tracking-widest opacity-30 text-emerald-500/70 tech-font">喜好事物+</h3>
                <p className="text-[9px] leading-tight line-clamp-3">{info.likes}</p>
             </div>
          )}
          {info.dislikes && (
             <div className="space-y-0.5">
                <h3 className="text-[7.5px] font-bold uppercase tracking-widest opacity-30 text-rose-500/70 tech-font">厭惡事物-</h3>
                <p className="text-[9px] leading-tight line-clamp-3">{info.dislikes}</p>
             </div>
          )}
        </div>

        <div className="grid grid-cols-1 gap-y-0 pt-2 mt-auto border-t border-white/5">
          <TraitBar label="肌肉密度 MUSCLE" value={traits.muscles} left="纖細" right="健壯" />
          <TraitBar label="核心體溫 CORE_TEMP" value={traits.temperature} left="較低" right="較高" />
          <TraitBar label="發聲強度 VOICE_VOL" value={traits.voiceVolume} left="小聲" right="大聲" />
          <TraitBar label="感性指標 SENSITIVITY" value={traits.sensitivity} left="冷淡" right="豐沛" />
          <TraitBar label="進食習慣 APPETITE" value={traits.appetite} left="小胃" right="大胃" />
          <TraitBar label="耐酒精性 ALCOHOL" value={traits.alcoholTolerance} left="較差" right="極佳" />
          <TraitBar label="運動神經 PHYSICAL" value={traits.athleticism} left="較弱" right="卓越" />
          <TraitBar label="戰鬥方式 RANGE" value={traits.combatRange} left="遠程" right="近戰" />
          <TraitBar label="戰鬥傾向 PREF" value={traits.combatPref} left="避戰" right="享受" />
        </div>
      </div>

      {/* 版權聲明 */}
      <div className="absolute bottom-1 right-3 pointer-events-none opacity-40 text-[7px] font-sans tracking-tight" style={{ color: textColor }}>
        (C) SQUARE ENIX CO., LTD. All Rights Reserved.
      </div>

      {/* 科技風格角落裝飾 */}
      <div className="absolute top-0 left-0 w-6 h-6 border-t-2 border-l-2 pointer-events-none" style={{ borderColor: accentColor }} />
      <div className="absolute top-0 right-0 w-6 h-6 border-t-2 border-r-2 pointer-events-none" style={{ borderColor: accentColor }} />
