export type Orientation = 'portrait' | 'landscape';
export type BorderStyle = 'solid' | 'double' | 'dashed' | 'dotted';

export interface CharacterInfo {
  name: string;
  server: string;
  gender: string;
  race: string;
  age: string;
  height: string;
  orientation: string;
  job: string;
  personality: string;
  background: string;
  birthplace: string;
  likes: string;
  dislikes: string;
  selectedFont?: string;
  cardFontSize?: number; // 新增：角色卡文字大小縮放

  // Custom Styles
  customBorderColor?: string;
  customBgStart?: string;
  customBgEnd?: string;
  customTextColor?: string;
  customAccentColor?: string;
  customBorderStyle?: BorderStyle;
  customBorderWidth?: number;
}

export interface Traits {
  muscles: number;
  temperature: number;
  voiceVolume: number;
  voicePitch: number;
  sensitivity: number;
  appetite: number;
  tableManners: number;
  alcoholPref: number;
  alcoholTolerance: number;
  athleticism: number;
  combatPref: number;
  combatSkill: number;
  combatRange: number;
}

export interface ImageTransform {
  x: number;
  y: number;
  scale: number;
  rotate: number;
}

export interface FrameStyle {
  id: string;
  name: string;
  borderColor: string;
  bgStart: string;
  bgEnd: string;
  accentColor: string;
  textColor: string;
}

import React from 'react';

interface TraitSelectorProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  leftLabel: string;
  rightLabel: string;
}

const TraitSelector: React.FC<TraitSelectorProps> = ({ label, value, onChange, leftLabel, rightLabel }) => {
  const steps = [0, 25, 50, 75, 100];

  return (
    <div className="flex flex-col space-y-2 mb-4 group">
      <div className="flex justify-between items-center">
        <label className="text-[11px] font-bold text-slate-400 tech-font tracking-widest">{label}</label>
      </div>

      <div className="flex items-center justify-between bg-black/40 p-2 rounded border border-slate-800 transition-colors group-hover:border-amber-900/50">
        <span className="text-[10px] w-14 text-right text-slate-600 tech-font leading-tight pr-1 uppercase">{leftLabel}</span>

        <div className="flex items-center justify-between flex-1 px-4 relative">
          {/* Connector Line with glow */}
          <div className="absolute top-1/2 left-4 right-4 h-[2px] bg-slate-900 -translate-y-1/2 z-0"></div>

          {steps.map((step) => (
            <button
              key={step}
              onClick={() => onChange(step)}
              className={`relative z-10 w-2.5 h-2.5 transition-all duration-300 transform ${
                value === step 
                  ? 'bg-amber-400 scale-150 rotate-45 shadow-[0_0_12px_#fbbf24]' 
                  : 'bg-slate-800 hover:bg-slate-600'
              }`}
              title={`${step}%`}
            />
          ))}
        </div>

        <span className="text-[10px] w-14 text-left text-slate-600 tech-font leading-tight pl-1 uppercase">{rightLabel}</span>
      </div>
    </div>
  );
};

export default TraitSelector;

import React, { forwardRef } from 'react';
import { CharacterInfo, Traits, Orientation, FrameStyle, ImageTransform } from '../types';

interface CardProps {
  info: CharacterInfo;
  traits: Traits;
  orientation: Orientation;
  style: FrameStyle;
  image: string | null;
  transform: ImageTransform;
  id?: string;
}

const Card = forwardRef<HTMLDivElement, CardProps>(({ info, traits, orientation, style, image, transform, id }, ref) => {
  const isPortrait = orientation === 'portrait';
  const fontScale = (info.cardFontSize || 100) / 100;

  const borderColor = info.customBorderColor || style.borderColor;
  const bgStart = info.customBgStart || style.bgStart;
  const bgEnd = info.customBgEnd || style.bgEnd;
  const textColor = info.customTextColor || style.textColor;
