    height: isPortrait ? '60%' : '100%',
    padding: '1.5rem',
    paddingBottom: '2.5rem', 
    overflowY: 'auto',
    color: textColor,
    display: 'flex',
    flexDirection: 'column',
    gap: `${0.8 * fontScale}rem`,
